const input = $input.first().json;
const body = input.body || input;

// Validate
if (!body.campaign_name || !body.variants || body.variants.length < 2) {
  return [{ json: { error: true, message: 'Need campaign_name and at least 2 variants' } }];
}

const testId = `ab_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
const totalAudience = body.audience_size || 1000;
const testPercentage = body.test_percentage || 20; // 20% for testing
const testAudience = Math.floor(totalAudience * testPercentage / 100);
const perVariant = Math.floor(testAudience / body.variants.length);

const variants = body.variants.map((v, i) => ({
  variant_id: `${testId}_v${i}`,
  variant_label: String.fromCharCode(65 + i), // A, B, C...
  subject_line: v.subject_line,
  preview_text: v.preview_text || '',
  template_id: v.template_id || body.default_template_id,
  audience_size: perVariant,
  stats: { sent: 0, opened: 0, clicked: 0, converted: 0 }
}));

return [{
  json: {
    test_id: testId,
    campaign_name: body.campaign_name,
    client_id: body.client_id,
    variants: variants,
    total_audience: totalAudience,
    test_audience: testAudience,
    remaining_audience: totalAudience - testAudience,
    test_percentage: testPercentage,
    winning_metric: body.winning_metric || 'open_rate', // open_rate, click_rate, conversion_rate
    test_duration_hours: body.test_duration_hours || 24,
    status: 'created',
    from_email: body.from_email || 'marketing@company.com',
    segment_criteria: body.segment_criteria || {},
    created_at: new Date().toISOString()
  }
}];

const contacts = $input.all().map(i => i.json);
const testConfig = $node['Setup A/B Test'].json;
const variants = testConfig.variants;
const perVariant = Math.floor(contacts.length / variants.length);

const results = [];

for (let i = 0; i < variants.length; i++) {
  const start = i * perVariant;
  const end = i === variants.length - 1 ? contacts.length : start + perVariant;
  const variantContacts = contacts.slice(start, end);

  for (const contact of variantContacts) {
    results.push({
      json: {
        contact_id: contact.id,
        email: contact.email,
        first_name: contact.first_name,
        variant_id: variants[i].variant_id,
        variant_label: variants[i].variant_label,
        subject_line: variants[i].subject_line.replace('{{first_name}}', contact.first_name || 'there'),
        preview_text: variants[i].preview_text,
        template_id: variants[i].template_id,
        test_id: testConfig.test_id,
        from_email: testConfig.from_email
      }
    });
  }
}

return results;
